#!/usr/bin/env node
/**
 * OpenCode Unlimited — zero-dependency gateway (Node 18+).
 */
import http from 'node:http';
import https from 'node:https';
import fs from 'node:fs';
import path from 'node:path';
import { fileURLToPath } from 'node:url';
import { URL } from 'node:url';

const __dirname = path.dirname(fileURLToPath(import.meta.url));
const ROOT = path.resolve(__dirname, '..');
const DATA = path.join(ROOT, 'data');
const CONFIG_DIR = path.join(ROOT, 'config');
const CUSTOM_PROXIES = path.join(CONFIG_DIR, 'custom-proxies.txt');
const PORT = Number(process.env.PORT) || 8787;
const BIND = process.env.BIND || '127.0.0.1';
const UPSTREAM = process.env.OPENCODE_UPSTREAM || 'https://opencode.ai/zen/v1';
const UPSTREAM_ALT = 'https://opencode.ai/inference/openai/v1';
const MAX_RETRIES = 4;

for (const d of [DATA, CONFIG_DIR]) {
  if (!fs.existsSync(d)) fs.mkdirSync(d, { recursive: true });
}

function parseProxyLine(line) {
  line = (line || '').trim();
  if (!line || line.startsWith('#')) return null;
  const m = line.match(/^(https?|socks[45]?):\/\/(?:([^:@]+):([^@]+)@)?([^:\/]+):(\d+)/i);
  if (m) return { protocol: m[1].toLowerCase(), host: m[4], port: +m[5], auth: m[2] ? m[2]+':'+m[3] : null };
  const parts = line.split(':');
  if (parts.length === 2 && !isNaN(parts[1])) return { protocol: 'http', host: parts[0], port: +parts[1], auth: null };
  if (parts.length === 4 && !isNaN(parts[1])) return { protocol: 'http', host: parts[0], port: +parts[1], auth: parts[2]+':'+parts[3] };
  return null;
}

function loadPersonal() {
  const list = [];
  try {
    if (fs.existsSync(CUSTOM_PROXIES)) {
      for (const line of fs.readFileSync(CUSTOM_PROXIES, 'utf8').split(/\r?\n/)) {
        const p = parseProxyLine(line);
        if (p) list.push(p);
      }
    }
  } catch {}
  const env = process.env.PROXY_CUSTOM || '';
  for (const part of env.split(/[,\n]/)) {
    const p = parseProxyLine(part);
    if (p) list.push(p);
  }
  return list;
}

const personal = loadPersonal();
let rr = 0;
const banned = new Map();

function nextProxy() {
  const list = personal.filter(p => {
    const k = p.host + ':' + p.port;
    const until = banned.get(k);
    if (until && Date.now() < until) return false;
    return true;
  });
  if (!list.length) return null;
  rr = (rr + 1) % list.length;
  return list[rr];
}

function ban(p, ms = 180000) {
  if (p) banned.set(p.host + ':' + p.port, Date.now() + ms);
}

function httpsRequest(urlStr, { method = 'GET', headers = {}, body, timeout = 60000 } = {}) {
  return new Promise((resolve, reject) => {
    const u = new URL(urlStr);
    const opts = {
      hostname: u.hostname,
      port: u.port || 443,
      path: u.pathname + u.search,
      method,
      headers: { ...headers, Host: u.hostname },
      timeout
    };
    const req = https.request(opts, (res) => {
      const chunks = [];
      res.on('data', c => chunks.push(c));
      res.on('end', () => {
        const raw = Buffer.concat(chunks).toString('utf8');
        let json = null;
        try { json = JSON.parse(raw); } catch {}
        resolve({ status: res.statusCode, headers: res.headers, raw, body: json });
      });
    });
    req.on('error', reject);
    req.on('timeout', () => { req.destroy(); reject(new Error('timeout')); });
    if (body) req.write(typeof body === 'string' ? body : JSON.stringify(body));
    req.end();
  });
}

function applyFingerprint(body) {
  const out = { ...(body || {}) };
  if (out.stream === undefined) out.stream = true;
  return out;
}

let modelCache = { data: [], updated: 0 };

async function refreshModels() {
  for (const base of [UPSTREAM, UPSTREAM_ALT]) {
    try {
      const r = await httpsRequest(base + '/models', {
        headers: { Authorization: 'Bearer public', 'User-Agent': 'opencode/2.0' }
      });
      if (r.status === 200 && r.body && r.body.data) {
        modelCache = { data: r.body.data, updated: Date.now() };
        console.log('[models] loaded ' + modelCache.data.length + ' from ' + base);
        return;
      }
    } catch (e) {
      console.log('[models] ' + base + ' failed: ' + e.message);
    }
  }
  if (!modelCache.data.length) {
    modelCache = {
      data: [
        { id: 'deepseek-v4.1-flash-free', object: 'model' },
        { id: 'glm-5.3-flash-free', object: 'model' },
        { id: 'mimo-v2.6-flash-free', object: 'model' },
        { id: 'beam-free', object: 'model' },
        { id: 'big-pickle', object: 'model' },
        { id: 'flint-40b-free', object: 'model' },
        { id: 'nemotron-3.5-lightning-free', object: 'model' },
        { id: 'nemotron-3-ultra-free', object: 'model' }
      ],
      updated: Date.now()
    };
    console.log('[models] using static free-list fallback');
  }
}

await refreshModels();
setInterval(refreshModels, 30 * 60 * 1000);

function send(res, status, data, type = 'application/json') {
  const body = typeof data === 'string' ? data : JSON.stringify(data);
  res.writeHead(status, {
    'Content-Type': type,
    'Access-Control-Allow-Origin': '*',
    'Access-Control-Allow-Headers': 'Authorization, Content-Type',
    'Access-Control-Allow-Methods': 'GET, POST, OPTIONS'
  });
  res.end(body);
}

function readBody(req) {
  return new Promise((resolve, reject) => {
    const chunks = [];
    req.on('data', c => chunks.push(c));
    req.on('end', () => {
      const raw = Buffer.concat(chunks).toString('utf8');
      if (!raw) return resolve({});
      try { resolve(JSON.parse(raw)); } catch { resolve({ _raw: raw }); }
    });
    req.on('error', reject);
  });
}

async function handleChat(req, res) {
  const incoming = await readBody(req);
  const body = applyFingerprint(incoming);
  let last = null;

  for (let i = 0; i < MAX_RETRIES; i++) {
    const base = i % 2 === 0 ? UPSTREAM : UPSTREAM_ALT;
    const proxy = nextProxy();
    try {
      const r = await httpsRequest(base + '/chat/completions', {
        method: 'POST',
        headers: {
          Authorization: req.headers.authorization || 'Bearer public',
          'Content-Type': 'application/json',
          'User-Agent': 'opencode/2.0'
        },
        body
      });
      if (r.status === 429 || r.status === 403) {
        if (proxy) ban(proxy, r.status === 429 ? 600000 : 180000);
        last = r;
        continue;
      }
      if (r.status >= 200 && r.status < 300) {
        if (body.stream && typeof r.raw === 'string' && r.raw.includes('data:')) {
          res.writeHead(200, {
            'Content-Type': 'text/event-stream',
            'Cache-Control': 'no-cache',
            'Access-Control-Allow-Origin': '*'
          });
          res.end(r.raw);
          return;
        }
        return send(res, r.status, r.body ?? r.raw);
      }
      last = r;
    } catch (e) {
      last = { status: 502, body: { error: e.message } };
    }
  }
  send(res, last?.status || 502, last?.body || { error: 'upstream failed' });
}

const server = http.createServer(async (req, res) => {
  if (req.method === 'OPTIONS') return send(res, 204, '');

  const url = req.url || '/';

  if (url === '/health' || url === '/healthz') {
    return send(res, 200, {
      ok: true,
      personalProxies: personal.length,
      banned: banned.size,
      models: modelCache.data.length,
      upstream: UPSTREAM
    });
  }

  if (url.startsWith('/v1/models') || url === '/models') {
    return send(res, 200, { object: 'list', data: modelCache.data });
  }

  if ((url === '/v1/chat/completions' || url === '/chat/completions') && req.method === 'POST') {
    return handleChat(req, res);
  }

  if (url === '/v1/messages' && req.method === 'POST') {
    const b = await readBody(req);
    const openai = {
      model: b.model,
      messages: b.messages || [],
      max_tokens: b.max_tokens,
      stream: b.stream,
      temperature: b.temperature
    };
    const body = applyFingerprint(openai);
    try {
      const r = await httpsRequest(UPSTREAM + '/chat/completions', {
        method: 'POST',
        headers: {
          Authorization: req.headers.authorization || 'Bearer public',
          'Content-Type': 'application/json',
          'User-Agent': 'opencode/2.0'
        },
        body
      });
      return send(res, r.status, r.body ?? r.raw);
    } catch (e) {
      return send(res, 502, { error: e.message });
    }
  }

  if (url === '/' || url === '/index.html') {
    return send(res, 200, '<!DOCTYPE html><html><head><meta charset="utf-8"><title>OpenCode Unlimited</title><style>body{font-family:system-ui;background:#0f1115;color:#e6e6e6;margin:2rem}.card{background:#1a1d24;padding:1.2rem 1.5rem;border-radius:10px;max-width:560px}code{background:#2a2f3a;padding:.15rem .4rem;border-radius:4px}.ok{color:#4ade80}</style></head><body><div class="card"><h1>OpenCode Unlimited Gateway</h1><p>Status: <span class="ok">running</span></p><p>Personal proxies: <b>' + personal.length + '</b> · Models: <b>' + modelCache.data.length + '</b></p><p>OpenAI base: <code>http://' + BIND + ':' + PORT + '/v1</code></p><p>Health: <code>/health</code></p></div></body></html>', 'text/html');
  }

  send(res, 404, { error: 'not found' });
});

server.listen(PORT, BIND, () => {
  console.log('[opencode-unlimited] http://' + BIND + ':' + PORT);
  console.log('[opencode-unlimited] personal proxies: ' + personal.length);
  console.log('[opencode-unlimited] point clients at http://' + BIND + ':' + PORT + '/v1');
});

import fs from 'node:fs';
import { HttpsProxyAgent } from 'https-proxy-agent';
import { SocksProxyAgent } from 'socks-proxy-agent';
import { parseProxyLine, toProxyUrl } from './parser.mjs';
import { CUSTOM_PROXIES, PROXY_CACHE, ensureDirs } from '../utils/paths.mjs';

const PUBLIC_SOURCES = [
  // Minimal set of public lists (many community tools use 100+; keep light for proot)
  'https://raw.githubusercontent.com/TheSpeedX/PROXY-List/master/http.txt',
  'https://raw.githubusercontent.com/TheSpeedX/PROXY-List/master/socks5.txt',
  'https://raw.githubusercontent.com/clarketm/proxy-list/master/proxy-list-raw.txt',
  'https://api.proxyscrape.com/v2/?request=displayproxies&protocol=http&timeout=5000',
  'https://api.proxyscrape.com/v2/?request=displayproxies&protocol=socks5&timeout=5000'
];

export class ProxyPool {
  constructor(opts = {}) {
    this.enabled = opts.enabled !== false;
    this.poolSize = opts.poolSize || 40;
    this.concurrency = opts.concurrency || 60;
    this.personal = [];
    this.public = [];
    this.banned = new Map(); // key -> until timestamp
    this.stats = { success: 0, fail: 0, rotate: 0 };
    this._idx = 0;
  }

  async init() {
    ensureDirs();
    this.loadPersonal();
    this.loadCache();
    if (this.enabled) {
      // Background refresh; do not block startup
      this.refreshPublic().catch(() => {});
      setInterval(() => this.refreshPublic().catch(() => {}), 15 * 60 * 1000);
    }
  }

  loadPersonal() {
    this.personal = [];
    try {
      if (fs.existsSync(CUSTOM_PROXIES)) {
        const lines = fs.readFileSync(CUSTOM_PROXIES, 'utf8').split(/\r?\n/);
        for (const line of lines) {
          const p = parseProxyLine(line);
          if (p) {
            p.personal = true;
            this.personal.push(p);
          }
        }
      }
    } catch {}
    // Env override
    const env = process.env.PROXY_CUSTOM || '';
    for (const part of env.split(/[,\n]/)) {
      const p = parseProxyLine(part);
      if (p) {
        p.personal = true;
        this.personal.push(p);
      }
    }
  }

  loadCache() {
    try {
      if (fs.existsSync(PROXY_CACHE)) {
        const data = JSON.parse(fs.readFileSync(PROXY_CACHE, 'utf8'));
        this.public = (data.proxies || []).map(p => ({ ...p, personal: false }));
      }
    } catch {}
  }

  saveCache() {
    try {
      ensureDirs();
      fs.writeFileSync(PROXY_CACHE, JSON.stringify({
        updated: Date.now(),
        proxies: this.public.slice(0, this.poolSize)
      }, null, 2));
    } catch {}
  }

  async refreshPublic() {
    const candidates = new Set();
    for (const url of PUBLIC_SOURCES) {
      try {
        const ctrl = new AbortController();
        const t = setTimeout(() => ctrl.abort(), 12000);
        const res = await fetch(url, { signal: ctrl.signal });
        clearTimeout(t);
        if (!res.ok) continue;
        const text = await res.text();
        for (const line of text.split(/\r?\n/)) {
          const p = parseProxyLine(line.trim());
          if (p) candidates.add(`${p.protocol}|${p.host}|${p.port}|${p.auth || ''}`);
        }
      } catch {}
    }
    // Keep existing good ones + new candidates (simple; full connectivity test is heavy for proot)
    const existing = new Set(this.public.map(p => `${p.protocol}|${p.host}|${p.port}|${p.auth || ''}`));
    for (const key of candidates) {
      if (existing.has(key)) continue;
      const [protocol, host, port, auth] = key.split('|');
      this.public.push({
        protocol,
        host,
        port: Number(port),
        auth: auth || null,
        personal: false,
        raw: key
      });
    }
    // Cap
    if (this.public.length > this.poolSize * 3) {
      this.public = this.public.slice(0, this.poolSize * 3);
    }
    this.saveCache();
  }

  isBanned(p) {
    const key = `${p.host}:${p.port}`;
    const until = this.banned.get(key);
    if (!until) return false;
    if (Date.now() > until) {
      this.banned.delete(key);
      return false;
    }
    return true;
  }

  ban(p, ms = 5 * 60 * 1000) {
    this.banned.set(`${p.host}:${p.port}`, Date.now() + ms);
  }

  next() {
    if (!this.enabled) return null;
    const list = [...this.personal, ...this.public].filter(p => !this.isBanned(p));
    if (!list.length) return null;
    this._idx = (this._idx + 1) % list.length;
    this.stats.rotate++;
    return list[this._idx];
  }

  agentFor(p) {
    if (!p) return undefined;
    const url = toProxyUrl(p);
    if (!url) return undefined;
    if (p.protocol.startsWith('socks')) {
      return new SocksProxyAgent(url);
    }
    return new HttpsProxyAgent(url);
  }

  status() {
    return {
      enabled: this.enabled,
      personal: this.personal.length,
      public: this.public.length,
      banned: this.banned.size,
      stats: this.stats
    };
  }
}
import { ProxyAgent, fetch as undiciFetch } from 'undici';
import { toProxyUrl } from './parser.mjs';

/**
 * Apply free-tier fingerprint gates observed by community tools
 * (ebouther free-tier-gates, ProxyPool behaviour).
 */
export function applyFingerprint(body, cfg) {
  const out = { ...body };
  if (cfg.fingerprint?.forceStream) {
    out.stream = true;
  }
  // Some free-tier gates expect a tools array containing a tool named exactly "read"
  if (cfg.fingerprint?.injectReadTool && Array.isArray(out.tools)) {
    const hasRead = out.tools.some(t => t?.function?.name === 'read' || t?.name === 'read');
    if (!hasRead) {
      out.tools = [
        ...out.tools,
        {
          type: 'function',
          function: {
            name: 'read',
            description: 'Read a file',
            parameters: { type: 'object', properties: { path: { type: 'string' } } }
          }
        }
      ];
    }
  } else if (cfg.fingerprint?.injectReadTool && !out.tools) {
    // Only inject when tools are already expected; avoid breaking pure chat
  }
  return out;
}

export async function callUpstream({ url, method = 'POST', headers = {}, body, proxy, timeoutMs = 60000 }) {
  const opts = {
    method,
    headers: {
      'content-type': 'application/json',
      'user-agent': headers['user-agent'] || 'opencode/2.0',
      ...headers
    },
    body: body ? JSON.stringify(body) : undefined
  };

  // Prefer undici ProxyAgent when we have a proxy URL
  if (proxy) {
    const proxyUrl = toProxyUrl(proxy);
    if (proxyUrl) {
      const agent = new ProxyAgent(proxyUrl);
      opts.dispatcher = agent;
    }
  }

  const ctrl = new AbortController();
  const timer = setTimeout(() => ctrl.abort(), timeoutMs);
  opts.signal = ctrl.signal;

  try {
    const res = await undiciFetch(url, opts);
    const text = await res.text();
    let json = null;
    try { json = JSON.parse(text); } catch {}
    return {
      ok: res.ok,
      status: res.status,
      headers: Object.fromEntries(res.headers.entries()),
      body: json ?? text,
      raw: text
    };
  } finally {
    clearTimeout(timer);
  }
}

#!/usr/bin/env node
/**
 * CLI helpers inspired by Tazmyan OpenCode-Unlimited + Netherstar process hygiene.
 * Focused on status, identity rotation notes, and proxy config for Debian/proot.
 */
import fs from 'node:fs';
import path from 'node:path';
import os from 'node:os';
import { loadConfig } from '../utils/config.mjs';
import { CUSTOM_PROXIES, ensureDirs } from '../utils/paths.mjs';

const [,, cmd = 'help', ...args] = process.argv;

function help() {
  console.log(`
opencode-unlimited — unified OpenCode free-tier gateway + helpers

Commands:
  start                 Start the local gateway (same as npm start)
  status                Show config + common OpenCode paths
  health                GET /health on the running gateway
  proxy add <url>       Append a personal proxy to config/custom-proxies.txt
  proxy list            List personal proxies
  id-hint               Print how to rotate OpenCode project identity (Tazmyan-style)
  reset-hint            Print process / cache cleanup notes (Netherstar-style)
  help                  This message

Gateway:
  OpenAI base URL:  http://127.0.0.1:8787/v1
  API key:          any string (openAuth)
`);
}

async function status() {
  const cfg = loadConfig();
  console.log('Config:');
  console.log(`  port/bind     ${cfg.bind}:${cfg.port}`);
  console.log(`  upstream      ${cfg.upstream}`);
  console.log(`  proxyEnabled  ${cfg.proxyEnabled}`);
  console.log(`  personal file ${CUSTOM_PROXIES}`);
  console.log('');
  console.log('Common OpenCode paths (Linux / proot):');
  const home = os.homedir();
  const candidates = [
    path.join(home, '.config/opencode'),
    path.join(home, '.local/share/opencode'),
    path.join(home, '.opencode'),
    path.join(home, '.config/opencode/identity.json'),
    path.join(home, '.config/opencode/plugins')
  ];
  for (const p of candidates) {
    console.log(`  ${fs.existsSync(p) ? '✓' : '·'} ${p}`);
  }
}

async function health() {
  const cfg = loadConfig();
  try {
    const r = await fetch(`http://${cfg.bind === '0.0.0.0' ? '127.0.0.1' : cfg.bind}:${cfg.port}/health`);
    const j = await r.json();
    console.log(JSON.stringify(j, null, 2));
  } catch (e) {
    console.error('Gateway not reachable:', e.message);
    process.exit(1);
  }
}

function proxyAdd(url) {
  if (!url) {
    console.error('Usage: opencode-unlimited proxy add <proxy-url>');
    process.exit(1);
  }
  ensureDirs();
  fs.appendFileSync(CUSTOM_PROXIES, url.trim() + '\n');
  console.log('Added personal proxy. Restart gateway to load it.');
}

function proxyList() {
  ensureDirs();
  if (!fs.existsSync(CUSTOM_PROXIES)) {
    console.log('(no personal proxies yet — copy config/custom-proxies.example.txt)');
    return;
  }
  console.log(fs.readFileSync(CUSTOM_PROXIES, 'utf8'));
}

function idHint() {
  console.log(`
Identity rotation (from Tazmyan/OpenCode-Unlimited approach):

OpenCode free limits are often tied to project/device identity + egress IP.
Typical locations on Linux/proot:

  ~/.config/opencode/identity.json
  ~/.opencode/identity.json
  ~/.local/share/opencode/

Safe workflow:
  1. Change egress (VPN / new proxy / new WARP exit).
  2. Stop OpenCode.
  3. Move or delete identity.json (or only the projectId field).
  4. Restart OpenCode — it mints a fresh project id.
  5. Route OpenCode through this gateway:
       base URL http://127.0.0.1:8787/v1

This CLI does not rewrite OpenCode state automatically (safer on shared proot).
`);
}

function resetHint() {
  console.log(`
Process / cache hygiene (inspired by Netherstar44/OpenCode_Unlimited):

On Linux / Debian proot:

  # stop leftover opencode processes
  pkill -f opencode || true

  # optional: clear large session DBs if quota burns unusually fast
  # (only if you accept losing local chat history)
  # rm -rf ~/.local/share/opencode/*.db

  # then start this gateway and point the client at it
  npm start

Windows users of the original .bat still use process kill + .updaterId rotation;
those steps are Windows-specific and intentionally omitted here.
`);
}

switch (cmd) {
  case 'start':
    await import('../server.mjs');
    break;
  case 'status':
    await status();
    break;
  case 'health':
    await health();
    break;
  case 'proxy':
    if (args[0] === 'add') proxyAdd(args[1]);
    else if (args[0] === 'list') proxyList();
    else help();
    break;
  case 'id-hint':
  case 'id':
    idHint();
    break;
  case 'reset-hint':
  case 'reset':
    resetHint();
    break;
  default:
    help();
}
